#include <iostream>
#include <vector>
#include <cmath>
using namespace std;

bool isPerfectSquare(int num) {
    int root = sqrt(num);
    return root * root == num;
}

bool validDataPackets(const vector<int>& packetList) {
    vector<int> validPackets;

    // Filter out odd integers
    for (int packet : packetList) {
        if (packet % 2 == 0) {
            validPackets.push_back(packet);
        }
    }

    if (validPackets.size() % 2 != 0) return false;

    for (size_t i = 0; i < validPackets.size(); i += 2) {
